css:
.pm-chapter-container {
  --ink: #1a202c;
  --muted: #718096;
  --accent: #2C5282;
  --warm: #DD6B20;
  --line: #e2e8f0;
  --paper: #f7fafc;
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 24px;
  line-height: 1.6;
  font-size: 16px;
  box-sizing: border-box;
}

.pm-chapter-container * {
  box-sizing: border-box;
}

.pm-title {
  font-size: 24px;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 8px;
  border-bottom: 2px solid var(--line);
  padding-bottom: 8px;
}

.pm-summary {
  font-size: 15px;
  color: var(--muted);
  margin-bottom: 24px;
}

.pm-layout-grid {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 24px;
}

@media (max-width: 768px) {
  .pm-layout-grid {
    grid-template-columns: 1fr;
  }
}

.pm-stepper-controls {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  padding: 12px;
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
}

.pm-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  padding: 8px 16px;
  border-radius: 4px;
  cursor: pointer;
  font-size: 14px;
  font-weight: 600;
}

.pm-btn:hover {
  opacity: 0.9;
}

.pm-btn:disabled {
  background: var(--muted);
  cursor: not-allowed;
}

.pm-step-indicator {
  font-weight: 600;
  color: var(--ink);
  min-width: 80px;
  text-align: center;
}

.pm-visualization-area {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 16px;
  min-height: 400px;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: auto;
}

.pm-text-flow {
  margin-top: 16px;
  background: #fff;
  padding: 16px;
  border-left: 4px solid var(--accent);
  border-radius: 4px;
}

.pm-text-content {
  font-size: 15px;
  margin: 0;
}

.pm-side-panel {
  display: flex;
  flex-direction: column;
  gap: 24px;
}

.pm-acceptance-interface,
.pm-sources-panel {
  background: #fff;
  border: 1px solid var(--line);
  border-radius: 6px;
  padding: 16px;
}

.pm-panel-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--accent);
  margin-bottom: 12px;
  border-bottom: 1px solid var(--line);
  padding-bottom: 8px;
}

.pm-control-group {
  margin-bottom: 12px;
}

.pm-control-group label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--ink);
}

.pm-control-group select,
.pm-control-group input {
  width: 100%;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 4px;
  font-size: 14px;
}

.pm-toggle-btn {
  width: 100%;
  padding: 6px;
  background: #edf2f7;
  border: 1px solid var(--line);
  border-radius: 4px;
  cursor: pointer;
  font-size: 13px;
}

.pm-toggle-btn[aria-pressed="true"] {
  background: var(--warm);
  color: #fff;
  border-color: var(--warm);
}

.pm-output-display {
  margin-top: 16px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
}

.pm-data-box {
  background: #f7fafc;
  border: 1px solid var(--line);
  padding: 8px;
  font-family: monospace;
  font-size: 12px;
  color: var(--muted);
  word-break: break-all;
  min-height: 40px;
}

.pm-source-list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.pm-source-list li {
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 8px;
  padding-left: 8px;
  border-left: 2px solid var(--line);
}

.pm-teaching-note {
  margin-top: 24px;
  padding: 12px;
  background: #fffaf0;
  border: 1px solid #fbd38d;
  border-radius: 4px;
  font-size: 13px;
  color: #744210;
}

/* SVG Styles */
.pm-svg-rect {
  fill: #fff;
  stroke: var(--accent);
  stroke-width: 2;
}
.pm-svg-text {
  font-size: 12px;
  fill: var(--ink);
  font-family: sans-serif;
}
.pm-svg-mask {
  fill: var(--warm);
  opacity: 0.3;
}
.pm-svg-flow {
  stroke: var(--accent);
  stroke-width: 2;
  fill: none;
  marker-end: url(#arrowhead);
}
.pm-svg-highlight {
  fill: #ebf8ff;
  stroke: var(--accent);
  stroke-width: 3;
}

javascript:
(function() {
  'use strict';

  // State Management
  const state = {
    step: 0,
    layers: 6,
    dModel: 512,
    maskVisible: false,
    steps: [
      {
        title: "输入嵌入与编码",
        text: "输入序列首先被转换为向量表示，进入编码器栈。编码器由 6 层组成，每层并行计算所有位置的自注意力，捕捉全局依赖，随后通过前馈网络处理特征。",
        sourceIds: ["pdf-bdfaa68d8984f0dc-p3-b3", "pdf-bdfaa68d8984f0dc-p3-b1"]
      },
      {
        title: "解码器自注意力（带掩码）",
        text: "解码器接收上一步的输出（或目标序列的前缀）。其第一子层是自注意力，但应用了掩码，使得位置 i 只能关注位置 <i 的信息，防止偷看未来答案。",
        sourceIds: ["pdf-bdfaa68d8984f0dc-p3-b4"]
      },
      {
        title: "编码器 - 解码器注意力",
        text: "解码器的第二子层（实际上是整个解码器层的第三个子层）执行多头注意力。此时 Query 来自解码器上一层，而 Key 和 Value 来自编码器的最终输出，实现源序列与目标序列的对齐。",
        sourceIds: ["pdf-bdfaa68d8984f0dc-p3-b4"]
      },
      {
        title: "前馈与输出生成",
        text: "经过注意力层后，数据通过逐位置前馈网络，最后经线性变换和 Softmax 生成下一个符号的概率分布。整个过程重复直到生成结束标记。",
        sourceIds: ["pdf-bdfaa68d8984f0dc-p3-b4", "pdf-bdfaa68d8984f0dc-p2-b11"]
      }
    ]
  };

  // DOM Elements
  const container = document.getElementById('transformer-architecture');
  if (!container) return;

  const svgEl = document.getElementById('transformer-architecture-svg');
  const stepIndicator = document.getElementById('transformer-architecture-step-indicator');
  const textContainer = document.getElementById('transformer-architecture-text-container');
  const btnPrev = document.getElementById('transformer-architecture-step-prev');
  const btnNext = document.getElementById('transformer-architecture-step-next');
  const selectLayers = document.getElementById('transformer-architecture-layer-count');
  const toggleMask = document.getElementById('transformer-architecture-mask-toggle');
  const inputDModel = document.getElementById('transformer-architecture-dmodel');
  const outputDisplay = document.getElementById('transformer-architecture-ai-output');
  const sourceList = document.getElementById('transformer-architecture-source-list');

  // Data Access
  const sourcesData = window.paperMindData && window.paperMindData.sources ? window.paperMindData.sources : {};
  const scopeSources = ["S036", "S037"];

  // Helper: Get Source Text
  function getSourceText(id) {
    if (sourcesData[id]) {
      return sourcesData[id].quote.substring(0, 60) + '... (p.' + sourcesData[id].page + ')';
    }
    return '来源不可用';
  }

  // Render Sources
  function renderSources() {
    sourceList.innerHTML = '';
    scopeSources.forEach(sid => {
      const li = document.createElement('li');
      li.textContent = getSourceText(sid);
      sourceList.appendChild(li);
    });
  }

  // Render SVG Architecture
  function renderSVG() {
    svgEl.innerHTML = '';
    const ns = 'http://www.w3.org/2000/svg';

    // Definitions
    const defs = document.createElementNS(ns, 'defs');
    const marker = document.createElementNS(ns, 'marker');
    marker.setAttribute('id', 'arrowhead');
    marker.setAttribute('markerWidth', '10');
    marker.setAttribute('markerHeight', '7');
    marker.setAttribute('refX', '10');
    marker.setAttribute('refY', '3.5');
    marker.setAttribute('orient', 'auto');
    const polygon = document.createElementNS(ns, 'polygon');
    polygon.setAttribute('points', '0 0, 10 3.5, 0 7');
    polygon.setAttribute('fill', '#2C5282');
    marker.appendChild(polygon);
    defs.appendChild(marker);
    svgEl.appendChild(defs);

    // Layout Constants
    const encoderX = 100;
    const decoderX = 500;
    const layerHeight = 40;
    const gap = 10;
    const totalHeight = state.layers * (layerHeight + gap) + 40;

    // Adjust SVG Viewbox based on layers
    svgEl.setAttribute('viewBox', `0 0 800 ${Math.max(600, totalHeight + 100)}`);

    // Encoder Stack
    const encGroup = document.createElementNS(ns, 'g');
    const encLabel = document.createElementNS(ns, 'text');
    encLabel.setAttribute('x', encoderX + 60);
    encLabel.setAttribute('y', 30);
    encLabel.setAttribute('text-anchor', 'middle');
    encLabel.setAttribute('class', 'pm-svg-text');
    encLabel.textContent = `编码器 (N=${state.layers})`;
    encGroup.appendChild(encLabel);

    for (let i = 0; i < state.layers; i++) {
      const y = 50 + i * (layerHeight + gap);
      const rect = document.createElementNS(ns, 'rect');
      rect.setAttribute('x', encoderX);
      rect.setAttribute('y', y);
      rect.setAttribute('width', 120);
      rect.setAttribute('height', layerHeight);
      rect.setAttribute('class', 'pm-svg-rect');
      if (state.step === 0) rect.setAttribute('class', 'pm-svg-highlight');
      encGroup.appendChild(rect);

      const text = document.createElementNS(ns, 'text');
      text.setAttribute('x', encoderX + 60);
      text.setAttribute('y', y + 25);
      text.setAttribute('text-anchor', 'middle');
      text.setAttribute('class', 'pm-svg-text');
      text.textContent = `层 ${i + 1}`;
      encGroup.appendChild(text);
    }
    svgEl.appendChild(encGroup);

    // Decoder Stack
    const decGroup = document.createElementNS(ns, 'g');
    const decLabel = document.createElementNS(ns, 'text');
    decLabel.setAttribute('x', decoderX + 60);
    decLabel.setAttribute('y', 30);
    decLabel.setAttribute('text-anchor', 'middle');
    decLabel.setAttribute('class', 'pm-svg-text');
    decLabel.textContent = `解码器 (N=${state.layers})`;
    decGroup.appendChild(decLabel);

    for (let i = 0; i < state.layers; i++) {
      const y = 50 + i * (layerHeight + gap);
      const rect = document.createElementNS(ns, 'rect');
      rect.setAttribute('x', decoderX);
      rect.setAttribute('y', y);
      rect.setAttribute('width', 120);
      rect.setAttribute('height', layerHeight);
      rect.setAttribute('class', 'pm-svg-rect');
      if (state.step === 1 || state.step === 2) rect.setAttribute('class', 'pm-svg-highlight');
      decGroup.appendChild(rect);

      // Mask Visualization in Decoder Step 1
      if (state.step === 1 && state.maskVisible && i === state.layers - 1) {
        const maskGroup = document.createElementNS(ns, 'g');
        // Draw a small 3x3 matrix next to the last layer
        const matrixX = decoderX + 130;
        const matrixY = y + 5;
        const cellSize = 10;
        for (let r = 0; r < 3; r++) {
          for (let c = 0; c < 3; c++) {
            const cell = document.createElementNS(ns, 'rect');
            cell.setAttribute('x', matrixX + c * cellSize);
            cell.setAttribute('y', matrixY + r * cellSize);
            cell.setAttribute('width', cellSize);
            cell.setAttribute('height', cellSize);
            cell.setAttribute('stroke', '#ccc');
            cell.setAttribute('fill', '#fff');
            // Upper triangle mask
            if (c > r) {
              cell.setAttribute('class', 'pm-svg-mask');
            }
            maskGroup.appendChild(cell);
          }
        }
        const maskLabel = document.createElementNS(ns, 'text');
        maskLabel.setAttribute('x', matrixX);
        maskLabel.setAttribute('y', matrixY + 35);
        maskLabel.setAttribute('class', 'pm-svg-text');
        maskLabel.textContent = '掩码 (dk=3 示例)';
        maskGroup.appendChild(maskLabel);
        svgEl.appendChild(maskGroup);
      }

      const text = document.createElementNS(ns, 'text');
      text.setAttribute('x', decoderX + 60);
      text.setAttribute('y', y + 25);
      text.setAttribute('text-anchor', 'middle');
      text.setAttribute('class', 'pm-svg-text');
      text.textContent = `层 ${i + 1}`;
      decGroup.appendChild(text);
    }
    svgEl.appendChild(decGroup);

    // Flow Lines
    if (state.step >= 1) {
      const flow = document.createElementNS(ns, 'path');
      flow.setAttribute('d', `M ${encoderX + 120} ${50 + (state.layers - 1) * (layerHeight + gap) + 20} C ${encoderX + 200} ${50 + (state.layers - 1) * (layerHeight + gap) + 20}, ${decoderX - 50} ${50 + (state.layers - 1) * (layerHeight + gap) + 20}, ${decoderX} ${50 + (state.layers - 1) * (layerHeight + gap) + 20}`);
      flow.setAttribute('class', 'pm-svg-flow');
      svgEl.appendChild(flow);
    }
  }

  // Render Text
  function renderText() {
    const stepData = state.steps[state.step];
    textContainer.innerHTML = `<h4 class="pm-title" style="font-size:18px;margin-bottom:8px;">${stepData.title}</h4><p class="pm-text-content">${stepData.text}</p>`;

    // Add source buttons
    const sourceContainer = document.createElement('div');
    sourceContainer.style.marginTop = '12px';
    stepData.sourceIds.forEach(sid => {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.setAttribute('data-source', sid);
      btn.textContent = '原文 · p.' + (sourcesData[sid] ? sourcesData[sid].page : '?');
      btn.style.fontSize = '12px';
      btn.style.marginRight = '8px';
      btn.style.padding = '4px 8px';
      btn.style.background = '#edf2f7';
      btn.style.border = '1px solid #ccc';
      btn.style.cursor = 'pointer';
      sourceContainer.appendChild(btn);
    });
    textContainer.appendChild(sourceContainer);
  }

  // Update Acceptance Output
  function updateAcceptanceOutput() {
    const data = [
      state.step,
      state.layers,
      state.dModel,
      state.maskVisible ? 1 : 0
    ];
    outputDisplay.setAttribute('data-values', JSON.stringify(data));
    outputDisplay.textContent = JSON.stringify(data);
  }

  // Update UI State
  function updateUI() {
    stepIndicator.textContent = `步骤 ${state.step + 1}/${state.steps.length}`;
    btnPrev.disabled = state.step === 0;
    btnNext.disabled = state.step === state.steps.length - 1;
    toggleMask.setAttribute('aria-pressed', state.maskVisible ? 'true' : 'false');
    toggleMask.textContent = state.maskVisible ? '开启' : '关闭';
    renderSVG();
    renderText();
    updateAcceptanceOutput();
  }

  // Event Listeners
  btnPrev.addEventListener('click', () => {
    if (state.step > 0) {
      state.step--;
      updateUI();
    }
  });

  btnNext.addEventListener('click', () => {
    if (state.step < state.steps.length - 1) {
      state.step++;
      updateUI();
    }
  });

  selectLayers.addEventListener('change', (e) => {
    state.layers = parseInt(e.target.value, 10);
    updateUI();
  });

  toggleMask.addEventListener('click', () => {
    state.maskVisible = !state.maskVisible;
    updateUI();
  });

  inputDModel.addEventListener('change', (e) => {
    const val = parseInt(e.target.value, 10);
    if (!isNaN(val) && val > 0) {
      state.dModel = val;
      updateUI();
    }
  });

  // Initialize
  renderSources();
  updateUI();

})();
